-- ST-I17: no biometrics. Employee fields can't be named for, or offer choices about, biometric data.
-- Same words as BIOMETRIC_LABEL in src/domain/biometrics.ts; keep the two in step. NOT VALID so an old field never blocks the deploy; new and edited fields are checked.
ALTER TABLE "staff_custom_fields" DROP CONSTRAINT IF EXISTS "staff_custom_fields_not_biometric";--> statement-breakpoint
ALTER TABLE "staff_custom_fields" ADD CONSTRAINT "staff_custom_fields_not_biometric" CHECK ("label" !~* '(^|[^a-z])(biometrics?|finger ?prints?|thumb ?prints?|face ?(scan|print|template|geometry|id|match)s?|facial (recognition|scan|geometry|template)s?|retina(l)?( scan)?s?|iris (scan|print)s?|voice ?prints?|hand ?(geometry|scan)s?|palm ?(print|vein)s?)([^a-z]|$)' AND "options"::text !~* '(^|[^a-z])(biometrics?|finger ?prints?|thumb ?prints?|face ?(scan|print|template|geometry|id|match)s?|facial (recognition|scan|geometry|template)s?|retina(l)?( scan)?s?|iris (scan|print)s?|voice ?prints?|hand ?(geometry|scan)s?|palm ?(print|vein)s?)([^a-z]|$)') NOT VALID;
